package com.sparkforge.studio;

import android.content.Context;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import com.android.apksig.ApkSigner;
import org.json.JSONObject;
import java.io.File;
import java.io.FileOutputStream;
import java.io.FilterOutputStream;
import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.KeyPairGenerator;
import java.security.KeyStore;
import java.security.PrivateKey;
import java.security.cert.X509Certificate;
import java.util.Arrays;
import android.util.Base64;
import java.util.Collections;
import java.util.Calendar;
import java.util.Date;
import java.util.Enumeration;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;
import javax.security.auth.x500.X500Principal;

/** Repackages an actual prebuilt Android game runner and signs it locally.
 * Does not invoke Gradle on the user's phone and does not require a server.
 */
final class OfflineApkExporter {
    private static final String KEY_ALIAS = "SparkForgeLocalSignerV1";
    private OfflineApkExporter() {}
    private static final class CounterStream extends FilterOutputStream {
        long position;
        CounterStream(OutputStream out) { super(out); }
        @Override public void write(int b) throws IOException { out.write(b); position++; }
        @Override public void write(byte[] b, int off, int len) throws IOException {
            out.write(b, off, len); position += len;
        }
    }
    /** Android 11+ requires resources.arsc to be STORED and four-byte aligned. */
    private static void storeAligned(ZipEntry entry, byte[] data, long outputPos) {
        CRC32 checksum=new CRC32(); checksum.update(data);
        entry.setMethod(ZipEntry.STORED);
        entry.setSize(data.length);
        entry.setCompressedSize(data.length);
        entry.setCrc(checksum.getValue());
        int nameLength=entry.getName().getBytes(StandardCharsets.UTF_8).length;
        int padding=(int)((4-((outputPos + 30 + nameLength + 4)%4))%4);
        byte[] extra=new byte[4+padding];
        extra[0]=(byte)0xFE; extra[1]=(byte)0xCA; extra[2]=(byte)padding; extra[3]=0;
        entry.setExtra(extra);
    }
    private static byte[] fixResourcePackage(byte[] data,String packageName) throws IOException {
        byte[] before="com.sparkforge.generated.aaaaaaaa".getBytes(StandardCharsets.UTF_16LE);
        byte[] after=packageName.getBytes(StandardCharsets.UTF_16LE);
        if(before.length!=after.length)throw new IOException("Invalid generated package length");
        int hits=0;
        for(int i=0;i<=data.length-before.length;i++) {
            boolean match=true;
            for(int j=0;j<before.length;j++) if(data[i+j]!=before[j]) { match=false; break; }
            if(match) { System.arraycopy(after,0,data,i,after.length);hits++;i+=before.length-1; }
        }
        if(hits==0)throw new IOException("Resource package placeholder missing");
        return data;
    }
    static File build(Context ctx,String gameJson) throws Exception {
        JSONObject game=new JSONObject(gameJson);
        String name=game.optString("name","Моя игра").trim();
        if(name.length()==0)name="Моя игра";
        if(name.length()>55)name=name.substring(0,55);
        String identifier=game.optString("id","unnamed");
        int digest=identifier.hashCode();
        StringBuilder suffix=new StringBuilder();
        for(int i=0;i<8;i++)suffix.append((char)('a'+((digest >>> (i*4))&15)));
        String packageName="com.sparkforge.generated."+suffix;
        File unsigned=File.createTempFile("sf-unsigned-", ".apk",ctx.getCacheDir());
        File signed=File.createTempFile("sf-signed-", ".apk",ctx.getCacheDir());
        boolean manifestSeen=false;
        try {
            try (InputStream source=ctx.getAssets().open("runner-template.apk");
                 ZipInputStream zip=new ZipInputStream(source);
                 CounterStream counter=new CounterStream(new FileOutputStream(unsigned));
                 ZipOutputStream out=new ZipOutputStream(counter)) {
                ZipEntry entry;
                byte[] buffer=new byte[32768];
                while((entry=zip.getNextEntry())!=null) {
                    String path=entry.getName();
                    if(entry.isDirectory()||path.equals("assets/game.json") ||
                            path.matches("META-INF/[^/]+\\.(RSA|DSA|EC|SF|MF)")) continue;
                    byte[] data;
                    if(path.endsWith("/spark_icon.png") && game.optString("appIcon", "").startsWith("data:image/png;base64,")) {
                        String iconData=game.getString("appIcon");
                        data=Base64.decode(iconData.substring(iconData.indexOf(',')+1),Base64.DEFAULT);
                        if(data.length>1000000)throw new IOException("Icon exceeds limit");
                    } else if(path.equals("AndroidManifest.xml") || path.equals("resources.arsc")) {
                        java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();
                        int n;while((n=zip.read(buffer))!=-1)bytes.write(buffer,0,n);
                        if(path.equals("AndroidManifest.xml")) {
                            data=BinaryManifest.change(bytes.toByteArray(),packageName,name);
                            manifestSeen=true;
                        } else data=fixResourcePackage(bytes.toByteArray(),packageName);
                    } else {
                        data=null;
                    }
                    ZipEntry target=new ZipEntry(path);
                    if(path.equals("resources.arsc")) storeAligned(target,data,counter.position);
                    out.putNextEntry(target);
                    if(data!=null)out.write(data);
                    else {int n;while((n=zip.read(buffer))!=-1)out.write(buffer,0,n);}
                    out.closeEntry();
                    zip.closeEntry();
                }
                if(!manifestSeen)throw new IllegalStateException("Missing runner manifest");
                out.putNextEntry(new ZipEntry("assets/game.json"));
                out.write(gameJson.getBytes(StandardCharsets.UTF_8));
                out.closeEntry();
            }
            KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);
            if(!ks.containsAlias(KEY_ALIAS)) {
                KeyPairGenerator gen=KeyPairGenerator.getInstance("RSA","AndroidKeyStore");
                Calendar cal=Calendar.getInstance();cal.add(Calendar.YEAR,20);
                KeyGenParameterSpec params=new KeyGenParameterSpec.Builder(KEY_ALIAS,
                        KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY)
                    .setKeySize(3072)
                    .setDigests(KeyProperties.DIGEST_SHA256,KeyProperties.DIGEST_SHA512)
                    .setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1)
                    .setCertificateSubject(new X500Principal("CN=SparkForge User Game Export"))
                    .setCertificateSerialNumber(BigInteger.ONE)
                    .setCertificateNotBefore(new Date(System.currentTimeMillis()-86400000L))
                    .setCertificateNotAfter(cal.getTime()).build();
                gen.initialize(params);gen.generateKeyPair();
            }
            PrivateKey key=(PrivateKey)ks.getKey(KEY_ALIAS,null);
            X509Certificate cert=(X509Certificate)ks.getCertificate(KEY_ALIAS);
            ApkSigner.SignerConfig signer=new ApkSigner.SignerConfig.Builder(
                    "sparkforge",key,Collections.singletonList(cert)).build();
            new ApkSigner.Builder(Collections.singletonList(signer))
                    .setInputApk(unsigned).setOutputApk(signed)
                    .setV1SigningEnabled(false).setV2SigningEnabled(true)
                    .setV3SigningEnabled(true).build().sign();
            return signed;
        } catch (Exception ex) {
            signed.delete();throw ex;
        } finally {unsigned.delete();}
    }
}

package com.sparkforge.studio;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** Rebuilds the Android binary XML StringPool, keeping every string index intact.
 * The runner template uses literal label and package placeholders, no styled strings.
 */
final class BinaryManifest {
    private static int u16(byte[] a, int at) { return (a[at]&255)|((a[at+1]&255)<<8); }
    private static int i32(byte[] a,int at) { return ByteBuffer.wrap(a,at,4).order(ByteOrder.LITTLE_ENDIAN).getInt(); }
    private static void out16(ByteArrayOutputStream o,int v) {o.write(v&255);o.write((v>>8)&255);}
    private static void out32(ByteArrayOutputStream o,int v) {o.write(v&255);o.write((v>>8)&255);o.write((v>>16)&255);o.write((v>>24)&255);}
    private static int[] length8(byte[] a,int pos) {int n=a[pos]&255;if((n&0x80)==0)return new int[]{n,pos+1};return new int[]{((n&0x7f)<<8)|(a[pos+1]&255),pos+2};}
    private static int[] length16(byte[] a,int pos) {int n=u16(a,pos);if((n&0x8000)==0)return new int[]{n,pos+2};return new int[]{((n&0x7fff)<<16)|u16(a,pos+2),pos+4};}
    private static void writeLen8(ByteArrayOutputStream o,int n) {if(n>127){o.write(((n>>8)&127)|128);o.write(n&255);}else o.write(n);}
    private static void writeLen16(ByteArrayOutputStream o,int n){if(n>32767){out16(o,((n>>16)&32767)|0x8000);out16(o,n&65535);}else out16(o,n);}

    static byte[] change(byte[] xml,String packageName,String title) throws IOException {
        if(u16(xml,0)!=0x0003)throw new IOException("Not a binary AndroidManifest.xml");
        int p=8;
        if(u16(xml,p)!=0x0001)throw new IOException("String pool not found");
        int chunkSize=i32(xml,p+4),count=i32(xml,p+8),styles=i32(xml,p+12),flags=i32(xml,p+16),start=i32(xml,p+20);
        if(styles!=0)throw new IOException("Styled AXML string pool unsupported");
        if(count<1||count>10000||start>chunkSize||p+chunkSize>xml.length)throw new IOException("Invalid manifest string pool");
        boolean utf8=(flags&0x100)!=0;
        List<String> strings=new ArrayList<>();
        for(int i=0;i<count;i++) {
            int at=p+start+i32(xml,p+28+4*i);
            if(utf8) {
                int[] c=length8(xml,at),b=length8(xml,c[1]);
                strings.add(new String(xml,b[1],b[0],StandardCharsets.UTF_8));
            } else {
                int[] c=length16(xml,at);
                strings.add(new String(xml,c[1],c[0]*2,StandardCharsets.UTF_16LE));
            }
        }
        boolean replacedPkg=false,replacedTitle=false;
        for(int i=0;i<strings.size();i++) {
            if(strings.get(i).equals("com.sparkforge.generated.aaaaaaaa")) {
                strings.set(i,packageName);replacedPkg=true;
            } else if(strings.get(i).equals("PROJECT_TITLE_PLACEHOLDER")) {
                strings.set(i,title);replacedTitle=true;
            }
        }
        if(!replacedPkg||!replacedTitle)throw new IOException("Template manifest placeholders missing");
        ByteArrayOutputStream data=new ByteArrayOutputStream();
        int[] offsets=new int[count];
        for(int i=0;i<count;i++) {
            String s=strings.get(i);offsets[i]=data.size();
            if(utf8){byte[] b=s.getBytes(StandardCharsets.UTF_8);writeLen8(data,s.length());writeLen8(data,b.length);data.write(b);data.write(0);}
            else {byte[] b=s.getBytes(StandardCharsets.UTF_16LE);writeLen16(data,s.length());data.write(b);out16(data,0);}
        }
        while(data.size()%4!=0)data.write(0);
        int stringStart=28+4*count;
        int newSize=stringStart+data.size();
        ByteArrayOutputStream pool=new ByteArrayOutputStream();
        out16(pool,1);out16(pool,28);out32(pool,newSize);
        out32(pool,count);out32(pool,0);out32(pool,flags);out32(pool,stringStart);out32(pool,0);
        for(int offset:offsets)out32(pool,offset);
        data.writeTo(pool);
        ByteArrayOutputStream result=new ByteArrayOutputStream();
        result.write(xml,0,4);out32(result,xml.length-chunkSize+newSize);
        result.write(xml,8,p-8);pool.writeTo(result);
        result.write(xml,p+chunkSize,xml.length-p-chunkSize);
        return result.toByteArray();
    }
}

package com.sparkforge.studio;

import android.app.Activity;
import android.content.ContentValues;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Environment;
import android.provider.MediaStore;
import android.webkit.JavascriptInterface;
import android.webkit.WebChromeClient;
import android.webkit.ValueCallback;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import android.widget.Toast;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.json.JSONObject;

public final class MainActivity extends Activity {
    private WebView web;
    private static final int PICK_FILE = 901;
    private ValueCallback<Uri[]> fileCallback;
    private final ExecutorService worker = Executors.newSingleThreadExecutor();

    @Override public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().setStatusBarColor(0xff141322);
        getWindow().setNavigationBarColor(0xff10101e);
        web = new WebView(this);
        web.setBackgroundColor(0xff0b0b16);
        web.getSettings().setJavaScriptEnabled(true);
        web.getSettings().setDomStorageEnabled(true);
        web.getSettings().setAllowFileAccess(true);
        web.getSettings().setAllowFileAccessFromFileURLs(true);
        web.setWebViewClient(new WebViewClient());
        web.setWebChromeClient(new WebChromeClient() {
            @Override public boolean onShowFileChooser(WebView v, ValueCallback<Uri[]> callback,
                    FileChooserParams params) {
                if (fileCallback != null) fileCallback.onReceiveValue(null);
                fileCallback = callback;
                try { startActivityForResult(params.createIntent(), PICK_FILE);return true; }
                catch (Exception ex) {fileCallback = null;callback.onReceiveValue(null);return false;}
            }
        });
        web.addJavascriptInterface(new Bridge(), "SparkAndroid");
        setContentView(web);
        web.loadUrl("file:///android_asset/index.html");
    }

    private Uri toDownloads(String displayName, String mime, InputStream data) throws Exception {
        ContentValues values = new ContentValues();
        values.put(MediaStore.Downloads.DISPLAY_NAME, displayName.replace('/', '_').replace('\\', '_'));
        values.put(MediaStore.Downloads.MIME_TYPE, mime);
        values.put(MediaStore.Downloads.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/SparkForge");
        values.put(MediaStore.Downloads.IS_PENDING, 1);
        Uri uri = getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
        if (uri == null) throw new IllegalStateException("Downloads media provider unavailable");
        try {
            try (OutputStream out = getContentResolver().openOutputStream(uri)) {
                if (out == null) throw new IllegalStateException("Cannot open output");
                byte[] bytes = new byte[32768]; int n;
                while ((n = data.read(bytes)) != -1) out.write(bytes, 0, n);
            }
            ContentValues ready = new ContentValues();
            ready.put(MediaStore.Downloads.IS_PENDING, 0);
            getContentResolver().update(uri, ready, null, null);
            return uri;
        } catch (Exception ex) {
            getContentResolver().delete(uri, null, null);
            throw ex;
        }
    }
    private void callback(String msg) {
        runOnUiThread(() -> {if (web != null) web.evaluateJavascript(
                "window.sparkApkResult(" + JSONObject.quote(msg) + ");", null);});
    }
    public final class Bridge {
        @JavascriptInterface public void saveFile(String name, String content, String mime) {
            worker.execute(() -> {
                try {
                    java.io.ByteArrayInputStream in = new java.io.ByteArrayInputStream(
                            content.getBytes(StandardCharsets.UTF_8));
                    toDownloads(name, mime, in);
                    callback("Сохранено: Загрузки / SparkForge / " + name);
                } catch (Exception ex) { callback("Ошибка сохранения: " + ex.getMessage()); }
            });
        }
        @JavascriptInterface public void buildApk(String json) {
            worker.execute(() -> {
                try {
                    callback("Упаковка ресурсов игры…");
                    File apk = OfflineApkExporter.build(MainActivity.this, json);
                    String title = new JSONObject(json).optString("name", "Game");
                    Uri uri;
                    try (InputStream input = new FileInputStream(apk)) {
                        uri = toDownloads("game-" + Integer.toHexString(json.hashCode()) + ".apk",
                                "application/vnd.android.package-archive", input);
                    }
                    callback("APK создан: Загрузки / SparkForge");
                    runOnUiThread(() -> {
                        Intent intent = new Intent(Intent.ACTION_VIEW);
                        intent.setDataAndType(uri, "application/vnd.android.package-archive");
                        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
                        try { startActivity(intent); }
                        catch (Exception ex) { Toast.makeText(MainActivity.this,
                                "APK сохранён в Загрузки / SparkForge", Toast.LENGTH_LONG).show(); }
                    });
                    apk.delete();
                } catch (Exception ex) { callback("Сборка APK: " + ex.getMessage()); }
            });
        }
    }
    @Override protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == PICK_FILE && fileCallback != null) {
            Uri[] result = WebChromeClient.FileChooserParams.parseResult(resultCode, data);
            fileCallback.onReceiveValue(result);
            fileCallback = null;
        }
    }
    @Override protected void onDestroy() {
        worker.shutdownNow();
        if (web != null) {web.destroy(); web = null;}
        super.onDestroy();
    }
}

