package com.sparkforge.runner;

import android.app.Activity;
import android.os.Bundle;
import android.content.pm.ActivityInfo;
import android.view.WindowManager;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

public final class RunnerActivity extends Activity {
    private WebView web;

    @Override public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,
                WindowManager.LayoutParams.FLAG_FULLSCREEN);
        web = new WebView(this);
        web.getSettings().setJavaScriptEnabled(true);
        web.getSettings().setDomStorageEnabled(true);
        web.getSettings().setAllowFileAccess(true);
        web.setWebViewClient(new WebViewClient() {
            @Override public void onPageFinished(WebView view, String url) {
                try {
                    InputStream in = getAssets().open("game.json");
                    ByteArrayOutputStream out = new ByteArrayOutputStream();
                    byte[] buf = new byte[8192]; int n;
                    while ((n = in.read(buf)) >= 0) out.write(buf, 0, n);
                    in.close();
                    String json = out.toString(StandardCharsets.UTF_8.name());
                    JSONObject project=new JSONObject(json);
                    String orientation=project.optString("orientation","landscape");
                    if(orientation.equals("landscape"))setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);
                    else if(orientation.equals("portrait"))setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);
                    else setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);
                    view.evaluateJavascript("window.launchSpark(" + JSONObject.quote(json) + ");", null);
                } catch (Exception ex) {
                    view.evaluateJavascript("document.body.textContent='Ошибка игры: ' + "
                            + JSONObject.quote(ex.toString()) + ";", null);
                }
            }
        });
        setContentView(web);
        web.loadUrl("file:///android_asset/runner.html");
    }
    @Override protected void onDestroy() {
        if (web != null) { web.destroy(); web = null; }
        super.onDestroy();
    }
}
